  samenvatting:[
    '<h4>👑 Marcus Aurelius, de filosoof-keizer</h4><div class="lp-tegels"><div><i>📅</i><b>121 – 180</b><small>Romeinse keizer</small></div><div><i>💎</i><b>Verissimus</b><small>“de meest waarachtige”</small></div><div><i>🧠</i><b>filosoof-keizer</b><small>keizer én denker</small></div></div>',
    '<h4>⚔️ Een zware regering</h4><div class="lp-stroom"><div><span>161</span><b>keizer, samen met Lucius Verus</b></div><div><span>aan de grenzen</span><b>oorlogen</b></div><div class="groen"><span>in het rijk</span><b>grote pestepidemie</b></div></div>',
    '<h4>🏛️ Het stoïcisme</h4><p>Marcus Aurelius volgt het <b>stoïcisme</b>.</p><div class="lp-ketting"><span>±300 v.C.<br><b>Zeno van Citium</b><br><small>stichter</small></span><i>→</i><span><b>Seneca</b></span><i>→</i><span><b>Epictetus</b></span><i>→</i><span><b>Marcus Aurelius</b></span></div>',
    '<h4>⭐ De 4 stoïcijnse deugden</h4><div class="lp-tegels k2 t-groen"><div><i>🦉</i><b>wijsheid</b></div><div><i>🦁</i><b>moed</b></div><div><i>⚖️</i><b>rechtvaardigheid</b></div><div><i>🥄</i><b>matigheid</b></div></div><p class="lp-tip">💡 Ezelsbruggetje: <b>W-M-R-M</b>: <b>W</b>ijs, <b>M</b>oedig, <b>R</b>echtvaardig, <b>M</b>atig.</p>',
    '<h4>💭 Stoïcijnse ideeën</h4><div class="lp-tegels k2"><div><i>😌</i><b>emoties beheersen</b><small>je reactie kies je zelf</small></div><div><i>📋</i><b>je plicht doen</b></div><div><i>🔄</i><b>goed en slecht zijn relatief</b><small>het hangt af van hoe je ernaar kijkt</small></div><div><i>🌿</i><b>in harmonie met de natuur</b><small>wat goed is voor de zwerm, is goed voor de bij 🐝</small></div></div>',
    '<h4>📖 Meditaties (Tot zichzelf)</h4><div class="lp-tegels"><div><i>📚</i><b>12 boeken</b></div><div><i>📝</i><b>persoonlijke notities</b><small>voor zichzelf</small></div><div><i>🔒</i><b>niet voor publicatie</b><small>nooit zo bedoeld</small></div></div><p class="lp-kop">🗣️ Bekende gedachten</p><ul><li>We lijden meer in onze <b>verbeelding</b> dan in werkelijkheid.</li><li>Het leven is <b>kort</b>.</li><li>Je hebt macht over je <b>geest</b>, niet over wat er <b>buiten</b> gebeurt.</li></ul>',
    '<h4>✍️ Hoe schrijft hij?</h4><div class="lp-tegels k2"><div><i>💥</i><b>aforismen</b><small>korte, krachtige wijsheden</small></div><div><i>❓</i><b>retorische vragen</b><small>vragen zonder antwoord te verwachten</small></div><div><i>🌳</i><b>natuurmetaforen</b><small>beelden uit de natuur</small></div><div><i>🔁</i><b>herhaling en zelfaansporing</b><small>“Doe …”, “Denk eraan …”</small></div></div><div class="lp-vs"><div><b>🎨 stijl</b><u>eenvoudig en direct</u></div><div><b>🧩 structuur</b><u>fragmentarisch</u><small>losse gedachten, geen doorlopend verhaal</small></div></div>'
  ],
